INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('antipath','Antipath','minion','legitch',NULL,'','SCP Fragmented Veil','{"slug":"antipath","name":"Antipath","team":"minion","ability":"Each night*, you may choose a player: if the Demon, you die, otherwise, they die. If you''d die, you might not. Not in team info.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-682 is a hard to kill titanic reptile of immense regenerative capabilities and endurance, who isn''t fond of working with too many people.","summaryBullets":["The Antipath is effectively another Demon with the added benefit of situational immortality. However, at the cost of this power, the Antipath has a lack of friends to knowingly support immediately unless they play smart.","Not only does the Antipath not know who their Minions & Demon is, but the other Minions and the Demon don''t know who the Antipath is.","The Antipath can kill each night except the first, but may willingly choose not to attack during the night.","Lastly, if the Antipath would die for whatever reason, they might not."],"howToRun":["Do not do the Minion Info/Demon Info steps for the Antipath, and do not include them in said steps for other players.","Each night except the first, wake the Antipath. They either shake their head no or point at any player. Put the Antipath to sleep.","If the Antipath chose a player, that player {{i|dies}} - mark them with the **DEAD** reminder. If it was the Demon however, the Antipath dies instead.","If the Antipath would die, you may choose if they remain alive. If the Antipath was executed, declare either that they die or they remain alive {{i|(do not say why.)}}"],"tips":["If the Antipath were to kill themselves through their ability, you may choose to spare them or not, depending on the current game state and which team is winning."],"quote":"At the end of the day, the Foundation''s gotta eat some babies to save the world. That''s just the facts.","iconBy":"le_nuberto","jinxes":[{"name":"Fortune Teller","align":"good","text":"The Antipath is always the ''Red Herring'' to the Fortune Teller.","id":"fortuneteller"}],"customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"If you want to use a more lore-accurate Demon version of SCP-682, use this JSON, where its an admittedly uncreative mix between Pukka and Shabaloth.\n\nWhile setting up the game, before putting character tokens in the bag, add one extra Outsider character token and remove one Minion character token. You may also choose to add another extra Outsider character token and remove one Townsfolk character token.\n\nEach night, wake the Hartudeztroi. They point at 2 players. Put the Hartudeztroi to sleep. The chosen players are poisoned - mark them with a **POISONED** reminder.\n\nEach night except the first, the other players marked **POISONED** {{i|dies}} - mark them with a **DEAD** reminder, then remove their **POISONED** reminder.\n\n**Hartudeztroi █** (Demon)\nEach night, choose 2 players: they are poisoned. The previously poisoned players die, then become healthy. [-1 Minion, +1 or +2 Outsiders]\n\n**First night:** The Hartudeztroi points to 2 players. Those players are poisoned.\n**Other nights:** The Hartudeztroi points to a players. Those players are poisoned. The previously poisoned players die.\n**Reminders:** Poisoned, Poisoned, Dead, Dead\n**Setup:** yes\n**Credit:** Ability: @legitch. Image: @le_nuberto\n\n**Jinxes:**\nEngineer: If the Engineer swaps out the Hartudeztroi, a living player becomes a Minion & learns the evil team, prioritizing an Outsider. If the Engineer swaps in the Hartudeztroi, all players learn the Hartudeztroi is in-play.\nHatter: If the Hartudeztroi chooses to swap off, a living player becomes a Minion & learns the evil team, prioritizing an Outsider. If the Demon swaps into the Hartudeztroi, all players learn the Hartudeztroi is in-play.\nPit-Hag: If Pit-Hag chooses to swap off the Hartudeztroi, a living player becomes a Minion & learns the evil team, prioritizing an Outsider. If the Demon swaps into the Hartudeztroi, all players learn the Hartudeztroi is in-play.\nSummoner: The Summoner may choose themselves (& only themselves) to become the Hartudeztroi on the 2nd night.\nPorcher: The Demon cannot gain the Hartudeztroi''s ability. If the Hartudeztroi is in play & the Porcher dies, they instead wake to choose 1 player to become a evil (once).\nPenitent: When the Penitent dies, if the Hartudeztroi chooses to accept the 2nd Demon ability, they may instead choose 3 players to kill at night instead of 2."}],"firstNight":0,"otherNight":52.682,"reminders":["Dead"],"setup":false,"otherNightReminder":"The Antipath either shows the ''no'' head signal, or points to a player. If the Demon, the Antipath dies, otherwise, that player dies.","art":"art/antipath.png","jsonId":"antipath_scp_fragmented_veil","curata":false}','scp-fragmented-veil/antipath','published',datetime('now'),datetime('now')),
('disruptor','Disruptor','minion','legitch',NULL,'','SCP Fragmented Veil','{"slug":"disruptor","name":"Disruptor","team":"minion","ability":"Each odd/even (you know which) day & night, Townsfolk abilities yield false info. Non-info abilities might register you falsely.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Camera Disruptor (SCP-895) is an oak coffin that appears normal and harmless physically, but disrupts camera and field equipment every so often.","summaryBullets":["Townsfolk information will be forcibly made false half of the time during the game.","This will occur either during every even day and night, or every odd day and night.","The Disruptor wakes on their first night to learn which it is.","Townsfolk information being made false is unaffected by drunkenness or poisoning.","If any character has an ability that would detect or affect a good player and is not exclusively yielding information, then the Disruptor might register as good to that character. If any character has an ability that detects Townsfolk, Outsiders, or Demons, then the Disruptor might register as a specific Townsfolk, Outsider, or Demon to that player. It is the Storyteller''s choice as to what the Disruptor registers as, even as many characters or both alignments during the same night. This can occur even outside of odd/even-numbered days and nights."],"howToRun":["While preparing the first night, put either the Disruptor''s **ACTIVE** or **INACTIVE** reminder token by the Disruptor''s character token.","During the first night, wake the Disruptor. Show them the 1 finger signal if they are marked with the **ACTIVE** reminder token, or the 2 finger signal if they are marked with the **INACTIVE** reminder token. Put them to sleep.","Each dusk, replace the Disruptor''s **ACTIVE** reminder token with the **INACTIVE** reminder token, and vice-versa.","Whilst the Disruptor is marked **ACTIVE**, you must give false information whenever a Townsfolk ability prompts you to give information.","Each time the Disruptor is targeted by an ability not yielding information that detects or affects good characters or the Demon, you may choose to have them register as good & a good character or Demon of your choice. Do whatever is appropriate for allowing an ability to work that would normally only affect good, evil, Townsfolk, Outsider or Demon players."],"quote":"Wild MISSINGNO appeared!","iconBy":"le_nuberto","jinxes":[{"name":"Banshee","align":"good","text":"If the Disruptor''s false info is active and the Demon kills the Banshee, the players still learn that the Banshee has died.","id":"banshee"},{"name":"Ogre","align":"good","text":"The Disruptor registers as evil to the Ogre.","id":"ogre"},{"name":"Plague Doctor","align":"good","text":"If the Plague Doctor dies, a living Minion gains the Disruptor''s ability in addition to their own ability, and learns this.","id":"plaguedoctor"}],"customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"For if you want a less complex Disruptor with limitations on what info it can affect, use this JSON to instead make info abilities register good as evil, and vice-versa.\n\nThe Disruptor no longer wakes on the first night. Each time a player is targeted by an info-based ability that detects or affects good or evil players or characters, that player registers as being it from the opposite alignment. Do whatever is appropriate, such as showing a good character token, nodding, or giving finger signals.\n\nEach time the Disruptor is targeted by an ability not yielding information that detects or affects good characters, you may choose to have them register as good & a good character of your choice. Do whatever is appropriate for allowing an ability to work that would normally only affect good, evil, Townsfolk, Outsider or Minion players.\n\n**Disruptor █~** (Minion)\nGood info abilities register good as evil, & vice-versa. Non-info abilities might register you as good & a good character.\n\n**Credit:** Ability: @legitch. Image: @le_nuberto\n\n**Jinxes:**\nOgre: The Disruptor registers as evil to the Ogre.\nPlague Doctor: If the Plague Doctor dies, a living Minion gains the Disruptor''s ability in addition to their own ability, and learns this."}],"firstNight":12.895,"otherNight":0,"reminders":["Active","Inactive"],"setup":false,"firstNightReminder":"Show the 1 finger symbol if the Disruptor''s information ability will act on odd-numbered nights, or the 2 finger symbol if the Disruptor''s information ability will act on even-numbered nights.","art":"art/disruptor.png","jsonId":"disruptor_scp_fragmented_veil","curata":false}','scp-fragmented-veil/disruptor','published',datetime('now'),datetime('now')),
('atanip','Atañip','minion','legitch',NULL,'','SCP Fragmented Veil','{"slug":"atanip","name":"Atañip","team":"minion","ability":"Each night*, choose a player: a marked player, if chosen, is poisoned & dies next night. If you''re executed, you might not die.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Reverse Piñata (SCP-956) is an unbreakable pinata that has axe to grind against the scourge of their mark.","summaryBullets":["One to any amount of characters on the script are marked with the Atañip''s character icon to indicate they are the Atañip''s marked target.","If the Atañip correctly chooses a player with a character marked on the script at night, the marked character will be poisoned, and die from it the next night.","The poisoned player will die the next night, even if the Atañip''s guess was a failure that night the death occurs.","The Atañip does not know if they successfully chose a player with a marked character, but can rightfully infer on it based on their death the next night.","Lastly, if the Atañip would die by execution, they might not."],"howToRun":["On the script, place a mark on characters you want to be susceptible to the Atañip.","Each night except the first, the player marked **POISONED** {{i|dies}} - replace their **POISONED** reminder with the **DEAD** reminder. Wake the Atañip. They point at any player. Put the Atañip to sleep. If chosen player is a character marked on the script, they are poisoned - mark them with a **POISONED** reminder.","If the Atañip is executed, declare either that they die or they remain alive {{i|(do not say why.)}}"],"quote":"Another child broken in half today! 🥳","iconBy":"le_nuberto","jinxes":[{"name":"Kazali","align":"evil","text":"If the Kazali chooses the marked character to become a Minion, and the Atañip is in play, a good player becomes the marked character.","id":"kazali"},{"name":"Plague Doctor","align":"good","text":"If the Plague Doctor dies, a living Minion gains the Atañip''s ability in addition to their own ability, and learns this.","id":"plaguedoctor"},{"name":"Cawthane","align":"evil","text":"If the marked character is chosen to be the Cawthane & a Atañip, a good player becomes the marked character.","id":"cawthane_the_bootleggers_anthology"},{"name":"Caliban","align":"evil","text":"If the Demon makes the marked character into Caliban, and there is an alive Atañip, a different living player becomes the marked character and the Atañip learns this.","id":"caliban_circus_music"}],"customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"If you want the older version of the Atañip, which was more nuanced and complicated, use this JSON.\n\nOn the script, place a mark on the good character you want to be the target of the Atañip & their ability.\n\nWhile setting up the game, before putting character tokens in the bag, if the character marked on the script is not already in play, remove a Townsfolk character token and add the marked character token.\n\nEach night except the first, all Townsfolk that were poisoned by the Atañip killing the marked character become **healthy** - remove the **POISON ''TIL WAKE** reminder. Wake the Atañip. They point at any player. If they chose the marked character, they {{i|die}} - mark them with the **DEAD** reminder. If successful, all Townsfolk become poisoned - put the Atañip''s **POISON ''TIL WAKE** reminder in the center of the left side of the Grimoire. Put the Atañip to sleep.\n\nIf the Atañip is executed, declare that the player was executed but remains alive (do not say why.) All Townsfolk become poisoned - put the Atañip''s **POISON ''TIL DUSK** reminder in the center of the left side of the Grimoire.\n\nAt dusk tomorrow, all players poisoned by the Atañip become healthy - remove the **POISON ''TIL DUSK** reminder.\n\n**Atañip █~** (Minion)\nEach night*, choose a player: the marked character, if chosen, dies. If executed, you don''t die. If either occur, all Townsfolk are poisoned until tommorow. [+the mark]\n\n**Other nights:** All Townsfolk are no longer poisoned if you successfully killed the character marked on the script last night. The Atañip points to a player. If they point to the character marked on the script, they die, and if successful: all Townsfolk are poisoned.\n**Reminders:** Poison ''til wake, Poison ''til dusk, Dead\n**Setup:** yes\n**Credit:** Ability: @legitch. Image: @le_nuberto\n\n**Jinxes:**\nKazali: If the Kazali chooses the marked character to become a Minion, and the Atañip is in play, a good player becomes the marked character.\nPlague Doctor: If the Plague Doctor dies, a living Minion gains the Atañip''s ability in addition to their own ability, and learns this.\nCawthane: If the marked character is chosen to be the Cawthane & a Atañip, a good player becomes the marked character.\nCaliban: If the Demon makes the marked character into Caliban, and there is an alive Atañip, a different living player becomes the marked character and the Atañip learns this."}],"firstNight":0,"otherNight":53.956,"reminders":["Poisoned","Dead"],"setup":true,"otherNightReminder":"The Atañip points to a player. If that player is a marked character: That player is poisoned. The previously poisoned player dies.","art":"art/atanip.png","jsonId":"ataip_scp_fragmented_veil","curata":false}','scp-fragmented-veil/atanip','published',datetime('now'),datetime('now'));
